<?php
use App\Accounts\{DeviceAuth,Management};
use App\Domain\{Access,Failure};
use App\Imports\UserImports;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{DB,Route};
$admin=function(Request $r,bool $recent=false):object{$u=Access::user((int)$r->session()->get('uid'));Access::admin($u);if($recent)DeviceAuth::requireRecent($r);return $u;};
Route::get('/api/admin/users',function(Request $r)use($admin){$admin($r);$q=DB::table('users');if($r->filled('q')){$term='%'.str_replace(['%','_'],['\\%','\\_'],mb_substr($r->input('q'),0,100)).'%';$q->where(fn($a)=>$a->where('student_id','ilike',$term)->orWhere('name','ilike',$term));}return ['users'=>$q->orderBy('id')->paginate(20)->through(fn($u)=>Management::user($u))];});
Route::post('/api/admin/users',function(Request $r)use($admin){$u=$admin($r);$v=$r->validate(['name'=>'required|string|max:200','student_id'=>'required|string|min:6|max:100']);return ['user'=>Management::createUser((int)$u->id,$v)];});
Route::patch('/api/admin/users/{user}',function(Request $r,int $user)use($admin){$u=$admin($r,$r->hasAny(['role','disabled','student_id']));$v=$r->validate(['name'=>'sometimes|required|string|max:200','student_id'=>'sometimes|required|string|min:6|max:100','role'=>'sometimes|in:user,admin','disabled'=>'sometimes|boolean']);return ['user'=>Management::updateUser((int)$u->id,$user,$v)];})->whereNumber('user');
Route::post('/api/admin/users/{user}/reset-password',function(Request $r,int $user)use($admin){$u=$admin($r,true);$r->validate(['confirm'=>'required|accepted']);Management::resetPassword((int)$u->id,$user);return ['reset'=>true];})->whereNumber('user');
Route::post('/api/admin/users/{user}/revoke-sessions',function(Request $r,int $user)use($admin){$u=$admin($r,true);$r->validate(['confirm'=>'required|accepted']);if(!DB::table('users')->where('id',$user)->exists())throw new Failure('user_unavailable',404);DeviceAuth::revokeUser($user);DeviceAuth::audit((int)$u->id,'user.sessions_revoked',['user_id'=>$user]);return ['revoked'=>true];})->whereNumber('user');
Route::get('/api/admin/courses',function(Request $r)use($admin){$admin($r);$query=DB::table('courses')->select('courses.*')->selectRaw("(SELECT count(*) FROM lessons WHERE course_id=courses.id) AS lesson_count, (SELECT count(*) FROM lessons WHERE course_id=courses.id AND status<>'ended') AS active_count");if(!$r->boolean('deleted'))$query->whereNull('deleted_at');return ['courses'=>$query->orderBy('sort_order')->orderBy('id')->paginate(30)];});
$courseRules=['name'=>'required|string|max:200','description'=>'sometimes|nullable|string|max:5000','target_language'=>'sometimes|in:zh,en,uk','guest_access'=>'sometimes|in:public,link','enabled'=>'sometimes|boolean','allow_audio_download'=>'sometimes|boolean','sort_order'=>'sometimes|integer|min:-100000|max:100000','archived'=>'sometimes|boolean'];
Route::post('/api/admin/courses',function(Request $r)use($admin,$courseRules){$u=$admin($r,true);return ['course'=>Management::course((int)$u->id,null,$r->validate($courseRules))];});
Route::patch('/api/admin/courses/{course}',function(Request $r,int $course)use($admin,$courseRules){$u=$admin($r,true);$rules=$courseRules;$rules['name']='sometimes|required|string|max:200';return ['course'=>Management::course((int)$u->id,$course,$r->validate($rules))];})->whereNumber('course');
Route::delete('/api/admin/courses/{course}',function(Request $r,int $course)use($admin){$u=$admin($r,true);$r->validate(['confirm'=>'required|accepted']);Management::deleteCourse((int)$u->id,$course);return ['deleted'=>true];})->whereNumber('course');
Route::get('/api/admin/users/template.xlsx',function(Request $r)use($admin){$admin($r);$locale=$r->validate(['locale'=>'sometimes|in:zh-CN,en,uk'])['locale']??'zh-CN';return response()->download(app(UserImports::class)->template($locale),'users-template.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Cache-Control'=>'no-store'])->setPrivate()->deleteFileAfterSend();});
Route::post('/api/admin/imports',function(Request $r)use($admin){$u=$admin($r);$v=$r->validate(['file'=>'required|file|mimes:xlsx|max:4096','duplicate_policy'=>'sometimes|in:skip,update_name']);return app(UserImports::class)->preview($r->file('file')->getRealPath(),(int)$u->id,$v['duplicate_policy']??'skip');});
Route::get('/api/admin/imports/{import}',function(Request $r,string $import)use($admin){$u=$admin($r);return app(UserImports::class)->show($import,(int)$u->id,max(1,(int)$r->input('page',1)));})->whereUuid('import');
Route::post('/api/admin/imports/{import}/confirm',function(Request $r,string $import)use($admin){$u=$admin($r,true);$v=$r->validate(['confirm'=>'required|accepted','preview_hash'=>'required|string|size:64']);return app(UserImports::class)->confirm($import,(int)$u->id,$v['preview_hash']);})->whereUuid('import');
Route::get('/api/admin/imports/{import}/errors.csv',function(Request $r,string $import)use($admin){$u=$admin($r);return response()->download(app(UserImports::class)->errorsCsv($import,(int)$u->id),'import-errors.csv',['Content-Type'=>'text/csv; charset=UTF-8','Cache-Control'=>'no-store'])->setPrivate()->deleteFileAfterSend();})->whereUuid('import');

